import os
import torch
import random
import numpy as np


class Config:
    # --------------------------------------------------------------------------
    # Directory Setup
    # --------------------------------------------------------------------------
    # Base working directory for this specific idea
    WORKING_DIR = "./working/idea_9"

    # Input Metadata Paths (Generated by metadata script)
    TRAIN_META_PATH = "./metadata/train.csv"
    VAL_META_PATH = "./metadata/val.csv"
    TEST_META_PATH = "./metadata/test.csv"
    SAMPLE_SUBMISSION_PATH = "./input/sample_submission.csv"

    # Output Directories
    QA_CACHE_DIR = os.path.join(WORKING_DIR, "qa_cache")
    QA_MODELS_DIR = os.path.join(WORKING_DIR, "qa_models")

    TAPT_CACHE_DIR = os.path.join(WORKING_DIR, "tapt_cache")
    TAPT_OUTPUT_DIR = os.path.join(WORKING_DIR, "tapt_model_finetuned")
    TAPT_CHECKPOINT_DIR = os.path.join(WORKING_DIR, "tapt_checkpoints")

    SUBMISSION_DIR = os.path.join(WORKING_DIR, "submission")
    SUBMISSION_FILE = os.path.join(SUBMISSION_DIR, "submission.csv")

    # --------------------------------------------------------------------------
    # Model Architecture & Tokenizer
    # --------------------------------------------------------------------------
    # Base model checkpoint
    MODEL_CHECKPOINT = "xlm-roberta-base"

    # Sliding Window Parameters
    MAX_LENGTH = 384
    DOC_STRIDE = 128

    # --------------------------------------------------------------------------
    # Training Hyperparameters (QA Fine-tuning)
    # --------------------------------------------------------------------------
    BATCH_SIZE = 16
    LEARNING_RATE = 2e-5
    WEIGHT_DECAY = 0.01
    EPOCHS = 10
    WARMUP_RATIO = 0.1

    # Ensembling Seeds
    SEEDS = [42, 43, 44]

    # --------------------------------------------------------------------------
    # TAPT Hyperparameters (Masked Language Modeling)
    # --------------------------------------------------------------------------
    TAPT_BATCH_SIZE = 16
    TAPT_LEARNING_RATE = 2e-5
    TAPT_EPOCHS = 5
    MLM_PROBABILITY = 0.15

    # --------------------------------------------------------------------------
    # Inference / Post-processing
    # --------------------------------------------------------------------------
    N_BEST_SIZE = 20
    # Max answer length in tokens. EDA shows max words=51, so 128 tokens is safe.
    MAX_ANSWER_LENGTH = 128

    # --------------------------------------------------------------------------
    # Hardware
    # --------------------------------------------------------------------------
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 2

    @classmethod
    def setup(cls):
        """Creates necessary output directories."""
        dirs = [
            cls.WORKING_DIR,
            cls.QA_CACHE_DIR,
            cls.QA_MODELS_DIR,
            cls.TAPT_CACHE_DIR,
            cls.TAPT_OUTPUT_DIR,
            cls.TAPT_CHECKPOINT_DIR,
            cls.SUBMISSION_DIR,
        ]
        for d in dirs:
            os.makedirs(d, exist_ok=True)

    @staticmethod
    def set_seed(seed=42):
        """Sets the random seed for reproducibility."""
        random.seed(seed)
        np.random.seed(seed)
        torch.manual_seed(seed)
        torch.cuda.manual_seed_all(seed)
        # Ensure deterministic behavior
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False
        os.environ["PYTHONHASHSEED"] = str(seed)


# Initialize directories on module load
Config.setup()
